"""Manual affiliate banking and payout records. No bank transfer endpoint."""
def extend(spec):
 from authorization import object_schema,operation,parameter,REF,UUID
 schemas=spec['components']['schemas'];paths=spec['paths']
 nullable=lambda schema:{'anyOf':[schema,{'type':'null'}]}
 money={'type':'string','pattern':r'^\d+\.\d{2}$'};version={'type':'integer','minimum':0};instant={'type':'string','format':'date-time'}
 schemas['AffiliateBank']=object_schema({'id':UUID,'version':version,'revision':{'type':'integer','minimum':1},'bankName':{'type':'string','minLength':2,'maxLength':120},'accountName':{'type':'string','minLength':2,'maxLength':160},'accountLast4':{'type':'string','pattern':'^[0-9]{4}$'},'accountNumber':nullable({'type':'string','pattern':'^[0-9]{10}$'}),'status':{'type':'string','enum':['PENDING','APPROVED','REJECTED']},'reviewReason':nullable({'type':'string','maxLength':500})})
 schemas['AffiliatePayoutBalance']=object_schema({key:money for key in ['pending','available','held','reversed','paid','reserved','recovery']})
 schemas['AffiliatePayout']=object_schema({'id':UUID,'version':version,'period':{'type':'string','pattern':r'^\d{4}-(0[1-9]|1[0-2])$'},'state':{'type':'string','enum':['PREPARED','PAID','CANCELLED']},'amount':money,'transferReference':nullable({'type':'string','maxLength':120}),'createdAt':instant,'paidAt':nullable(instant)})
 schemas['AffiliatePayoutOverview']=object_schema({'partyId':UUID,'name':{'type':'string','maxLength':160},'affiliateState':{'type':'string','enum':['ACTIVE','SUSPENDED']},'bank':nullable(REF('AffiliateBank')),'balance':REF('AffiliatePayoutBalance'),'payouts':{'type':'array','maxItems':20,'items':REF('AffiliatePayout')},'page':{'type':'integer','minimum':0,'maximum':10000},'totalPages':version,'canPrepare':{'type':'boolean'},'canTransfer':{'type':'boolean'}})
 schemas['AffiliatePayoutPage']=object_schema({'items':{'type':'array','maxItems':20,'items':REF('AffiliatePayoutOverview')},'page':{'type':'integer','minimum':0,'maximum':10000},'totalPages':version})
 schemas['AffiliateBankInput']=object_schema({'expectedBankId':nullable(UUID),'bankName':{'type':'string','minLength':2,'maxLength':120},'accountName':{'type':'string','minLength':2,'maxLength':160},'accountNumber':{'type':'string','pattern':'^[0-9]{10}$'}})
 schemas['AffiliateBankReview']=object_schema({'bankId':UUID,'version':version,'decision':{'type':'string','enum':['APPROVED','REJECTED']},'reason':{'type':'string','minLength':3,'maxLength':500}})
 schemas['AffiliatePayoutPrepare']=object_schema({'bankId':UUID})
 schemas['AffiliatePayoutPaid']=object_schema({'version':version,'transferReference':{'type':'string','pattern':'^[A-Za-z0-9][A-Za-z0-9_./:-]{0,119}$'},'confirmTransferred':{'const':True}})
 schemas['AffiliatePayoutCancel']=object_schema({'version':version,'reason':{'type':'string','minLength':3,'maxLength':500},'confirmNoTransfer':{'const':True}})
 schemas['AffiliateBankReviewed']=object_schema({'saved':{'const':True}})
 page=parameter('page','query',{'type':'integer','minimum':0,'maximum':10000,'default':0});target=parameter('id','path',UUID,True)
 csrf=parameter('X-CSRF-TOKEN','header',{'type':'string','minLength':43,'maxLength':43},True)
 key=parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)
 staff='Current persisted ADMIN or FINANCE, normal login explicitly authorized. No MFA change for other operations. '
 def add(path,method,id,description,response,params,body=None):
  op=operation(id,description,response,params);op['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}}
  if body:op['requestBody']={'required':True,'content':{'application/json':{'schema':REF(body)}}}
  paths.setdefault(path,{})[method]=op
 add('/api/v1/me/affiliate/payouts','get','API-226','Current ACTIVE/SUSPENDED affiliate, own party only. Masked bank number, net payout balance and 20-row history. Paid/prepared totals are deducted from qualified commissions; post-paid refunds carry forward. No request body or unknown/repeated parameters.','AffiliatePayoutOverview',[page])
 add('/api/v1/me/affiliate/bank-details','put','API-227','Current ACTIVE affiliate only. Idempotency-Key is a random UUID, mapped one-way with party/purpose to the revision ID so public bank IDs cannot be reused as replay keys. Durable encrypted replay comparison includes expectedBankId. Ten-digit Nigerian number, manual staff review, no automatic bank verification. Current revision changes reset review; any PREPARED payout blocks edits. All bank data encrypted using contextual Commerce AES-GCM; no bank number in audit/idempotency responses.','AffiliatePayoutOverview',[csrf,parameter('Idempotency-Key','header',UUID,True)],'AffiliateBankInput')
 add('/api/v1/staff/affiliates','get','API-228',staff+'Bounded approved/suspended affiliates, masked bank details and payout balances. No unknown/repeated parameters or body.','AffiliatePayoutPage',[page])
 add('/api/v1/staff/affiliates/{id}/payouts','get','API-229',staff+'Explicit audited bank detail read returns full account number only here; current balance and 20-row payout history.','AffiliatePayoutOverview',[target,page])
 add('/api/v1/staff/affiliates/{id}/bank-review','post','API-230',staff+'Approve/reject only the current PENDING bank revision with expected version/reason; immutable account fields. Bank edits reset review. CSRF/idempotency and audit required.','AffiliateBankReviewed',[target,csrf,key],'AffiliateBankReview')
 add('/api/v1/staff/affiliates/{id}/payouts','post','API-231',staff+'Prepare and reserve the full current net available NGN balance with reviewed current bank details and active affiliate. One PREPARED per affiliate and one PREPARED/PAID per Africa/Lagos month. Server determines amount/month; no external transfer, automatic expiry or blind retry. Idempotency-Key must be a UUID and is the durable payout ID, so retries after temporary command-record expiry or a month change return the original payout.','AffiliatePayout',[target,csrf,parameter('Idempotency-Key','header',UUID,True)],'AffiliatePayoutPrepare')
 add('/api/v1/staff/affiliate-payouts/{id}/paid','post','API-232',staff+'Record external bank-confirmed payment only, with explicit attestation, unique bank reference and expected version. PREPARED -> PAID, no transfer API call. Preserve actual paid truth even if eligibility changes; refund recovery offsets future earnings. Uncertain bank outcome stays PREPARED; never create a second transfer.','AffiliatePayout',[target,csrf,key],'AffiliatePayoutPaid')
 add('/api/v1/staff/affiliate-payouts/{id}/cancel','post','API-233',staff+'Release PREPARED reservation only after explicit no-transfer-started attestation, expected version and reason. Uncertain or sent payments must not be cancelled. Audit/idempotent terminal record, no deletion.','AffiliatePayout',[target,csrf,key],'AffiliatePayoutCancel')
